-- League: a 4-player Commander league tracked per season.
-- Row ids inside a season are short text ids generated by the app (unique per season).
-- All writes go through the API with the service-role client, which enforces league rules.
-- Members can read everything in seasons they play in.

CREATE TABLE leagues (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  settings jsonb NOT NULL,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE league_seasons (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  league_id uuid NOT NULL REFERENCES leagues(id) ON DELETE CASCADE,
  number integer NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'ended')),
  week integer NOT NULL DEFAULT 1,
  version integer NOT NULL DEFAULT 0,
  ended_at timestamptz,
  ended_by text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (league_id, number)
);

CREATE TABLE league_members (
  season_id uuid NOT NULL REFERENCES league_seasons(id) ON DELETE CASCADE,
  id text NOT NULL,
  user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  name text NOT NULL,
  precon text NOT NULL DEFAULT '',
  role text NOT NULL DEFAULT 'player' CHECK (role IN ('player', 'commissioner')),
  PRIMARY KEY (season_id, id),
  UNIQUE (season_id, user_id)
);

CREATE INDEX league_members_user_id_idx ON league_members (user_id);

CREATE TABLE league_cards (
  season_id uuid NOT NULL REFERENCES league_seasons(id) ON DELETE CASCADE,
  id text NOT NULL,
  owner_id text NOT NULL,
  name text NOT NULL,
  type_line text NOT NULL DEFAULT '',
  rarity text NOT NULL DEFAULT 'common',
  origin text NOT NULL CHECK (origin IN ('precon', 'pull')),
  zone text NOT NULL CHECK (zone IN ('main', 'side')),
  commander boolean NOT NULL DEFAULT false,
  pack_id text,
  image_url text,
  image_checked boolean NOT NULL DEFAULT false,
  printing jsonb,
  color_identity jsonb,
  added_to_binder boolean NOT NULL DEFAULT false,
  PRIMARY KEY (season_id, id)
);

CREATE TABLE league_games (
  season_id uuid NOT NULL REFERENCES league_seasons(id) ON DELETE CASCADE,
  id text NOT NULL,
  number integer NOT NULL,
  week integer NOT NULL,
  results jsonb NOT NULL,
  logged_by text NOT NULL,
  logged_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (season_id, id),
  UNIQUE (season_id, number)
);

CREATE TABLE league_byes (
  season_id uuid NOT NULL REFERENCES league_seasons(id) ON DELETE CASCADE,
  member_id text NOT NULL,
  week integer NOT NULL,
  PRIMARY KEY (season_id, member_id)
);

CREATE TABLE league_packs (
  season_id uuid NOT NULL REFERENCES league_seasons(id) ON DELETE CASCADE,
  id text NOT NULL,
  member_id text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('opening', 'weekly', 'reserve', 'prize')),
  week integer NOT NULL,
  card_ids jsonb NOT NULL DEFAULT '[]',
  opened_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (season_id, id)
);

CREATE TABLE league_trades (
  season_id uuid NOT NULL REFERENCES league_seasons(id) ON DELETE CASCADE,
  id text NOT NULL,
  week integer NOT NULL,
  from_id text NOT NULL,
  to_id text NOT NULL,
  give_card_id text NOT NULL,
  get_card_id text NOT NULL,
  give_name text NOT NULL,
  get_name text NOT NULL,
  status text NOT NULL CHECK (status IN ('pending', 'accepted', 'declined', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  resolved_at timestamptz,
  PRIMARY KEY (season_id, id)
);

CREATE TABLE league_swaps (
  season_id uuid NOT NULL REFERENCES league_seasons(id) ON DELETE CASCADE,
  id text NOT NULL,
  week integer NOT NULL,
  member_id text NOT NULL,
  takes jsonb NOT NULL,
  at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (season_id, id)
);

CREATE TABLE league_changes (
  season_id uuid NOT NULL REFERENCES league_seasons(id) ON DELETE CASCADE,
  id text NOT NULL,
  week integer NOT NULL,
  game_number integer NOT NULL,
  member_id text NOT NULL,
  added_name text NOT NULL,
  removed_name text NOT NULL,
  source text NOT NULL,
  at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (season_id, id)
);

CREATE FUNCTION is_league_member(season uuid) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
  AS $$ SELECT EXISTS (SELECT 1 FROM league_members WHERE season_id = season AND user_id = auth.uid()) $$;

ALTER TABLE leagues ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_seasons ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_cards ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_games ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_byes ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_packs ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_trades ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_swaps ENABLE ROW LEVEL SECURITY;
ALTER TABLE league_changes ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Members can read their leagues" ON leagues FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM league_seasons s WHERE s.league_id = leagues.id AND is_league_member(s.id)));
CREATE POLICY "Members can read their seasons" ON league_seasons FOR SELECT TO authenticated USING (is_league_member(id));
CREATE POLICY "Members can read season members" ON league_members FOR SELECT TO authenticated USING (is_league_member(season_id));
CREATE POLICY "Members can read season cards" ON league_cards FOR SELECT TO authenticated USING (is_league_member(season_id));
CREATE POLICY "Members can read season games" ON league_games FOR SELECT TO authenticated USING (is_league_member(season_id));
CREATE POLICY "Members can read season byes" ON league_byes FOR SELECT TO authenticated USING (is_league_member(season_id));
CREATE POLICY "Members can read season packs" ON league_packs FOR SELECT TO authenticated USING (is_league_member(season_id));
CREATE POLICY "Members can read season trades" ON league_trades FOR SELECT TO authenticated USING (is_league_member(season_id));
CREATE POLICY "Members can read season swaps" ON league_swaps FOR SELECT TO authenticated USING (is_league_member(season_id));
CREATE POLICY "Members can read season changes" ON league_changes FOR SELECT TO authenticated USING (is_league_member(season_id));

GRANT ALL ON leagues, league_seasons, league_members, league_cards, league_games, league_byes,
  league_packs, league_trades, league_swaps, league_changes TO service_role;
